import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t as i,P as o,q as n}from"./D3cAVrQp.js";var r=i('<h1>Soil Health & Land Use Governance Framework v3.2.2</h1> <h2>Living Soil, Regenerative Land Use, Microbial Commons, and Constitutionally Bounded Land Authority</h2> <p><strong>Framework ID:</strong> <code>framework_soil_land</code><br> <strong>Document type:</strong> Tier 2 Systems for Long-Term Thriving — Core Governance Document<br> <strong>Version:</strong> 3.2.2<br> <strong>Date:</strong> 2026-08-02<br> <strong>Status:</strong> Controlled constitutional successor — cluster-conformant patch <strong>Conforms to:</strong> <code>CERGTA/0.1</code><br> <strong>Supersedes:</strong> Soil Health & Land Use Governance Framework v3.2.1 (editorial); substantive base v3.1<br> <strong>Authority effect:</strong> None until lawfully adopted in a jurisdiction</p> <hr> <h2>0. Controlled successor notice</h2> <p>Soil v3.2 preserves the source framework’s central vision: land as relation rather than commodity; living soil and microbial communities as foundations of food, water, health, biodiversity, and culture; Indigenous stewardship and rematriation; regenerative agriculture; seed and knowledge commons; community land trusts; temporal justice; urban–rural integration; and practical support for farmers and communities making a difficult transition.</p> <p>It replaces the v3.1 assumption that a BAZ, council, global accord, score, certificate, registry, target, future-being report, emergency label, or Treaty reference can move directly from soil concern to rights recognition, a land veto, a tax, a sale restriction, a title transfer, tenure revocation, trade sanction, emergency receivership, or coercive intervention.</p> <blockquote><p><strong>Soil urgency does not create land jurisdiction.</strong></p></blockquote> <blockquote><p><strong>Measurement is not mandate. Soil rights are not title. Planning is not adjudication. Community voice is not an unbounded veto. A tax is not a trade sanction. Certification is not a permit. A registry is not ownership. Emergency need is not receivership.</strong></p></blockquote> <p>This framework may observe, interpret, advise, deliberate, plan, educate, support restoration, administer separately chartered programmes or funds, prepare lawful records, and refer matters to competent authorities. It cannot create a global land sovereign, authenticate sacredness for another people, recognize rights, transfer title, rematriate land, impose universal taxes or bans, revoke tenure, allocate resettlement land, adjudicate claims, declare emergencies, or command coercive execution.</p> <h2>1. Source freeze and controlling instruments</h2> <table><thead><tr><th>Instrument</th><th>File</th><th>SHA-256</th></tr></thead><tbody><tr><td>Soil Health & Land Use Governance Framework v3.1</td><td><code>soil-health-land-use-governance-framework-v3.1.md</code></td><td><code>63a5e7518a6e5e7f0b05114d86538261c006b201752e1a54550f8ffbeddd8ecf</code></td></tr><tr><td>Commons/Ecological Authority Audit v0.1</td><td><code>commons-ecological-authority-cluster-constitutional-audit-v0.1.md</code></td><td><code>974dfd8dd4bf5b623bd5e7e544b7afdbbd89869b66f107db293cfe6af67a043b</code></td></tr><tr><td>CERGTA/0.1</td><td><code>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</code></td><td><code>3c45e37c834c727471657fc91149edbe3011137562c2dd73e54b20226c92589b</code></td></tr><tr><td>Hearthstone v2.0</td><td><code>hearthstone-protocol-v2.0.md</code></td><td><code>b6d50549977a3e50be6726bb5b1b94debddc3fb4d67aff1d2f9af08da65b1b2c</code></td></tr><tr><td>EIOI v2.7</td><td><code>ecological-intelligence-observation-interpretation-layer-v2.7.md</code></td><td><code>41cb7e607e8c3f8776ca74f3ba46ab0ff6bcce94fc24b35178fc4cd94d80d9a2</code></td></tr><tr><td>Planetary Health v0.9</td><td><code>planetary-health-governance-framework-v0.9.md</code></td><td><code>259083f6039180b4532ae168ff441245e526570c6442371814cbb238e669dc13</code></td></tr><tr><td>Biodiversity v1.1</td><td><code>biodiversity-implementation-framework-v1.1.md</code></td><td><code>8f29fa32ac4b76354030b55c61765a77e8c558d64e19627108d7c254d433ec1a</code></td></tr><tr><td>Water & Sanitation v5.2</td><td><code>water-sanitation-governance-framework-v5.2.md</code></td><td><code>3612de56de57d1940b278a7e7269588fc08cd964fd97bc33b8ebe8f7d7d69b97</code></td></tr><tr><td>Oceans & Marine Governance v2.3</td><td><code>oceans-marine-governance-framework-v2.3.md</code></td><td><code>fd9773579b9a5932eaec2ba9e8c73fb898ce91f9bbcb6aed50c77969f95418cf</code></td></tr><tr><td>Indigenous Sovereignty & Planetary Healing v1.1</td><td><code>indigenous-sovereignty-planetary-healing-v1.1.md</code></td><td><code>2e62ba2c00048ce20e4c9df7ffb9ce0338e358ee866e515bf102f4cc4e49df22</code></td></tr><tr><td>Justice Systems v1.4</td><td><code>justice-systems-framework-v1.4.md</code></td><td><code>08a8fdc78d6cd3928178cb5d98fdf8325b1fd4c9f016bb0c872e6b56b87d3ee4</code></td></tr><tr><td>ECRC/0.1</td><td><code>emergency-catastrophic-risk-continuity-interface-specification-v0.1.md</code></td><td><code>c673742b1317c7169d4b8226118478c990e9a3d05084b2dc5ac9ad2f1971163c</code></td></tr><tr><td>SCPA/0.1</td><td><code>security-coercion-protective-action-interface-specification-v0.1.md</code></td><td><code>b8f1dd0f676044542a23184f52200e50b106a798545c7c57119ded2c439b6299</code></td></tr></tbody></table> <p>A successor source or external framework does not enter this release merely because it has a higher version number or similar title. Compatibility requires controlled review and updated pins.</p> <p>This table is a <strong>provenance record</strong>: it identifies the exact texts read and audited when this successor was drafted. It is not the operative dependency set. The instruments this patch interoperates with are listed in Appendix A.1, and the authoritative machine-readable set is the cluster registry named in A.4. Where the two differ, A.1 governs. Digests are content hashes and remain valid under renaming; a filename here identifies an instrument, not a storage location.</p> <h2>2. Vision and constitutional purpose</h2> <p>Healthy soil is a living relationship among minerals, water, air, plants, animals, fungi, microbes, people, memory, work, and place. Soil governance therefore cannot be reduced either to private title or to a single ecological score. It must coordinate knowledge, rights, land law, food systems, housing, livelihoods, public health, ecological repair, and intergenerational responsibility while keeping their authorities visible and challengeable.</p> <p>The framework connects seven functions without merging them:</p> <ol><li><strong>ecological intelligence</strong> through EIOI-compatible soil and microbial observation, method, interpretation, uncertainty, and correction;</li> <li><strong>affected-nation and community authority</strong> through the specific Indigenous nations, customary systems, residents, tenants, workers, farmers, landless people, and food-system users concerned;</li> <li><strong>rights and guardianship pathways</strong> through CERGTA and separately competent legal authorities;</li> <li><strong>land, title, trust, and rematriation pathways</strong> through Hearthstone v2.0 and applicable property, Indigenous, public, and reparative law;</li> <li><strong>land-use, agricultural, tax, permit, and inspection powers</strong> only where individually enacted and institutionally separated;</li> <li><strong>transition finance and benefits</strong> through separately authorized funds, AUBI, insurance, procurement, and credit systems;</li> <li><strong>adjudication, emergency action, restoration, and enforcement</strong> through independent legal, CDEE/ECRC, CERGTA, and SCPA routes.</li></ol> <h2>3. Core principles</h2> <h3>3.1 Living soil without metaphysical compulsion</h3> <p>Soil may be treated ethically and, where law provides, legally as a living commons or rights-holder. The framework’s relational and sacred language guides care; it does not impose a metaphysical doctrine or create legal status by declaration.</p> <h3>3.2 Affected-nation authority</h3> <p>The specific affected Indigenous nation or nations determine representation, law, FPIC, sacred relations, land and sample authority, protected knowledge, and whether to engage. Global representation cannot consent for another people.</p> <h3>3.3 Land as relation with plural lawful interests</h3> <p>Title, customary tenure, occupancy, tenancy, stewardship, public duties, ecological rights, creditor interests, and reparative claims can coexist. No one category silently erases the others.</p> <h3>3.4 Observation–consequence separation</h3> <p>Soil samples, satellite imagery, AI outputs, dashboards, certificates, Love Ledger entries, BHI or LMCI modules, and thresholds may trigger review. They do not themselves create legal consequences.</p> <h3>3.5 Regeneration with food, housing, and livelihoods</h3> <p>Regenerative transition must protect food security, housing, workers, farmers, customary users, disability access, and essential water and services. Ecological gain cannot hide displacement or deprivation.</p> <h3>3.6 Microbial commons with sovereignty and biosafety</h3> <p>Microbial diversity and regenerative knowledge should be protected from enclosure, but “open source” never overrides affected-nation authority, sample provenance, biosafety, benefit sharing, privacy, or the right to withhold.</p> <h3>3.7 Precaution with review and expiry</h3> <p>Uncertainty may justify study, monitoring, a temporary pause, or a request for urgent protection. It does not justify indefinite restrictions, title transfer, receivership, guilt, or unreviewable power.</p> <h3>3.8 Just transition before withdrawal</h3> <p>Chemical restrictions, permit changes, subsidy reforms, land-use changes, certification consequences, and industry transition require alternatives, material support, sequencing, worker participation, and remedy.</p> <h3>3.9 Subsidiarity without automatic BAZ sovereignty</h3> <p>Bioregional governance can align institutions with ecological systems, but a BAZ label does not itself create land, tax, permit, court, emergency, or enforcement jurisdiction.</p> <h3>3.10 Every authority ends</h3> <p>Every plan, permit, grant, tax, restriction, inspection, investigation, mission, guardianship, stewardship mandate, and delegated power has review, expiry, termination, succession, data disposition, correction, and remedy.</p> <h2>4. Governance architecture</h2> <h3>4.1 Global Soil Knowledge and Monitoring Commons</h3> <p>The source Global Soil Health Monitoring Service is retained as a decentralized <strong>knowledge and method commons</strong>, not a regulator or title registry. It may maintain open methods, support community and low-tech monitoring, publish versioned soil assessments, coordinate laboratories, and preserve correction histories under EIOI v2.7 and the Aurora Accord.</p> <p>It cannot recognize soil rights, set binding thresholds, alter land-use permissions, impose certification, distribute money, identify legal guilt, declare emergencies, or activate enforcement. Its public dashboard must display method versions, uncertainty, missing evidence, dissent, community validation, protected-data omissions, and a prominent non-authority warning.</p> <h3>4.2 Bioregional Land and Food Councils</h3> <p>Councils are retained as locally grounded democratic institutions for deliberation, planning, knowledge exchange, conflict transformation, programme support, and—where expressly enacted—bounded administration. Their charters must identify each activated power and keep the following functions structurally separate:</p> <ul><li>public participation and land-use planning;</li> <li>Indigenous-nation liaison and protected-knowledge custody;</li> <li>technical soil assessment;</li> <li>regulatory standard, permit, cap, tax, or sale-review administration;</li> <li>grant, subsidy, insurance, AUBI-verification, and procurement functions;</li> <li>guardianship and stewardship representation;</li> <li>inspection and investigation;</li> <li>registry administration;</li> <li>mediation, adjudication, and appeal;</li> <li>emergency command and coercive execution.</li></ul> <p>Indigenous leadership and meaningful youth participation strengthen legitimacy but do not allow the Council to speak for an affected nation, impose a universal developmental model, or acquire unspecified jurisdiction.</p> <h3>4.3 Land, rematriation, and justice bodies</h3> <p>The source Land Rematriation and Justice Tribunal is not created as a universal court by this framework. A jurisdiction may constitute a specialized chamber, but it must be independent of Councils, guardians, funds, registries, monitors, and parties. Claims, title, trust constitution, rematriation, compensation, tenants, workers, creditors, registry correction, receivership, succession, and dissolution conform to Hearthstone v2.0 and CERGTA.</p> <p>Traditional justice and healing-centred processes may be used with the authority and consent of the affected people. They cannot be appropriated as compulsory procedure or used to bypass notice, evidence, counsel, independent review, appeal, or non-derogable rights.</p> <h3>4.4 Global Regenerative Agriculture Fund</h3> <p>The Fund is retained as a separately chartered financial institution or programme. Its governance, investment, grant approval, procurement, verification, audit, complaint, and recovery functions must be separated. It may support small-scale farmers, Indigenous stewards, workers, cooperatives, soil repair, insurance, research, and transition costs. It cannot make a soil standard legally binding, decide title, condition essential services on data surrender, or treat an ecological score as automatic eligibility, clawback, or fraud.</p> <p>The source figures—such as a fifteen-percent market premium for three years—remain illustrative policy options, not universal entitlements or rates.</p> <h3>4.5 Knowledge Commons and Open-Source Microbiome Bank</h3> <p>The Knowledge Commons may publish non-sensitive methods and support voluntary sharing. The Microbiome Bank is a network of local custodians, not a global owner of microbial cultures or Indigenous knowledge. Every contribution must record provenance, lawful collection, affected-nation and provider authority, access, biosafety, permitted uses, benefit sharing, derivative research, patent and publication conditions, return or destruction, and withdrawal where feasible.</p> <p>“Open source” applies only to material whose lawful custodians chose an open licence. It cannot be inferred from deposit, public funding, scientific interest, emergency need, or the framework’s commons philosophy.</p> <h3>4.6 Soil Emergency Assistance Missions</h3> <p>The source rapid-response mechanism is reconstituted as optional civilian technical missions under CDEE/ECRC. Missions may assess damage, support decontamination, preserve seed and microbial cultures, stabilize food production, coordinate laboratories and logistics, and assist recovery. They cannot allocate permanent resettlement land, alter title, impose land-use restrictions, conduct legal investigations, establish checkpoints, gather intelligence, search, seize, detain, or use force.</p> <h2>5. Affected Indigenous nations, customary law, and land relation</h2> <p>The affected Indigenous nation or nations—not a global council, Earth Council, BAZ, outside elder, scientist, spiritual representative, or framework-appointed guardian—determine their lawful representatives, territorial and relational authority, FPIC requirements, protected knowledge, sacred and cultural meaning, sample governance, internal plurality, dispute route, and whether to engage.</p> <p>A Council’s Indigenous composition governs the Council’s own decisions only. It cannot provide consent, define another nation’s territory, waive restitution, disclose knowledge, choose a trust, or accept compensation for the affected nation.</p> <p>Refusal or withdrawal cannot cause loss of environmental protection, food and water support, legal aid, grant eligibility unrelated to the refused activity, standing, or remedy. Missing documentary title cannot erase customary law, oral history, occupation, use, kinship, burial, sacred, or ecological evidence.</p> <h2>6. Soil as living commons and ecological rights</h2> <p>The framework supports legal recognition of soil systems, landscapes, microbial communities, and related ecological entities where competent law provides. The route is:</p> <ol><li>candidate and boundary intake;</li> <li>observation, protected knowledge, affected-interest mapping, and uncertainty;</li> <li>rights petition and standing;</li> <li>advisory recommendation and dissent;</li> <li>lawful recognition by a competent authority;</li> <li>rights catalogue, priority, conflicts, and non-derogation;</li> <li>separate guardian nomination and appointment;</li> <li>separate land, title, permit, remediation, and enforcement decisions.</li></ol> <p>Rights recognition does not itself transfer surface or subsoil title, invalidate leases, terminate farming, establish public access, assign carbon rights, appoint a guardian, or create a universal veto. Ecological rights and human, Indigenous, housing, food, water, disability, labour, and due-process rights must be made explicit rather than compressed into one aggregate “health” objective.</p> <h2>7. Land claims, title, rematriation, and the Hearthstone boundary</h2> <p>Soil v3.2 may identify ecological need, document evidence, support claimants, and prepare records. It does not itself decide title, rematriation, conveyance, trust constitution, compensation, debt, tenancy, registry priority, receivership, succession, or dissolution. Those matters route through Hearthstone v2.0 and applicable law.</p> <p>Before any land transition, the record must identify affected Indigenous nations, current and historical titleholders, customary users, occupants, tenants, farmers, workers, creditors, public services, food and water dependencies, neighbouring interests, ecological rights, and competing reparative claims.</p> <p>Rematriation means a return into a legal and relational form chosen by the affected people. It is not automatic transfer to a BAZ, Council, Community Land Trust, guardian, or framework-created institution. Soil restoration need may support urgency or interim non-prejudice; it does not eliminate claimants, compensation, housing, livelihoods, evidence, appeal, or independent adjudication.</p> <h2>8. Land-use plans and regenerative standards</h2> <p>Councils may co-produce land-use plans and Minimum Regenerative Standards using EIOI-compatible evidence, affected-nation law, local knowledge, food and housing needs, climate risks, watershed effects, biodiversity, animal welfare, workers, and alternatives.</p> <p>Every plan and standard must identify whether it is proposed, advisory, voluntarily adopted, contractual, locally enacted, nationally enacted, treaty-active, suspended, expired, or terminated. A standard does not become binding because it is scientifically desirable, approved by a Council, included in a dashboard, endorsed by a supermajority, or scheduled for a future phase.</p> <p>The source Bronze, Silver, and Gold thresholds—such as 25, 40, or 60 percent soil cover—remain illustrative certification parameters until a versioned method and competent adoption decision specify their meaning, regional adaptation, uncertainty, inspection, correction, and legal effect.</p> <h2>9. Regenerative agriculture mandates and chemical restrictions</h2> <p>Regenerative practices may include soil cover, reduced disturbance, living roots, crop and habitat diversity, context-sensitive livestock integration, nutrient cycling, reduced synthetic inputs, erosion control, water retention, fungal and microbial restoration, and farmer-led experimentation. No single practice list is universally optimal across arid, tropical, temperate, Arctic, urban, contaminated, or conflict-affected contexts.</p> <p>A binding mandate or restriction requires a competent authority, defined activity, evidence and uncertainty, affected farmers and workers, customary and Indigenous rights, food and water effects, alternatives, technical and financial support, transition period, exceptions, inspection rules, review, expiry, appeal, and remedy.</p> <p>A precautionary chemical phase-out may begin with monitoring, labelling, procurement change, subsidy reform, or time-limited restrictions. It cannot create predetermined fines, trade sanctions, criminal liability, or land forfeiture without separate law and adjudication.</p> <h2>10. Land-value tax, anti-speculation, and sale review</h2> <p>Land-value taxation and anti-speculation measures are policy options for jurisdictions, not powers created by this framework or by “Treaty trade leverage.” A valid tax identifies its legal source, valuation base, liable person, exemptions, agricultural and housing effects, Indigenous and customary protections, hardship relief, revenue use, notice, appeal, review, and expiry.</p> <p>A community right of first refusal requires lawful notice, eligible holders, valuation, financing, timelines, anti-circumvention, tenant and worker protections, completion, release, and review. The framework retires an unqualified <strong>Community Veto on Land Sales</strong>. Community and youth objections may require explanation, reconsideration, public reasons, or a lawful temporary pause; a binding restriction requires separately enacted authority, scope, duration, compensation where due, independent review, and remedy.</p> <h2>11. Stewardship leases, community land trusts, and food commons</h2> <p>A Generational Stewardship Lease is a lawful tenure instrument, not a score-controlled privilege. It must specify the legal interest, duration, rent or contribution, regenerative duties, housing and livelihood rights, investment and improvements, financing, insurance, succession, transfer, default, cure, termination, compensation, dispute route, and final land disposition.</p> <p>Community Land Trusts and Food Commons may support housing, agriculture, restoration, rewilding, sacred and cultural uses, public space, and microbial stewardship. Their title and trust constitution conform to Hearthstone v2.0. Designation as an ecopsychological healing site does not reduce tenant rights, create compulsory therapeutic participation, or automatically generate Hearts.</p> <h2>12. Stewardship performance, correction, and no-fault harm</h2> <p>Soil Health Scores, BHI modules, LMCI, Love Ledger, certification tiers, satellite data, and microbial indicators may support review. They cannot automatically terminate a lease, revoke a steward, replace a Council, freeze grants, demand repayment, transfer title, or activate receivership.</p> <p>Performance assessment must distinguish management from wildfire, drought, flood, war, upstream pollution, inherited contamination, climate change, invasive species, market shocks, inadequate finance, contradictory public policy, and measurement error. The normal sequence is evidence, response, independent verification, no-fault analysis, capacity support, correction plan, review, and only then a separately lawful suspension, succession, or termination decision.</p> <h2>13. Finance, AUBI, certification, and product passports</h2> <p>Financial and evidentiary routes remain separate:</p> <ul><li>a soil activity record verifies what occurred;</li> <li>an ecological record assesses contribution and uncertainty;</li> <li>a grant, AUBI, subsidy, insurance, procurement, premium, or credit authority independently decides eligibility and amount;</li> <li>an audit may correct records or seek lawful recovery;</li> <li>suspected fraud requires a separate investigation and adjudication route.</li></ul> <p>Certification and Digital Product Passports communicate bounded claims. They are not permits, market exclusions, trade sanctions, or proof of liability. Errors require correction propagation, interim relief, reassessment of dependent decisions, and compensation where applicable.</p> <h2>14. Soil carbon rights and registry</h2> <p>The source Soil Carbon Rights Registry is divided into method, benefit or ownership, credit issuance, transfer, retirement, reversal, and registry records. A carbon methodology must address baseline, additionality, permanence, leakage, soil depth, sampling, microbial contribution, uncertainty, climate reversals, double counting, and ecological side effects.</p> <p>A credit or carbon-benefit claim cannot be inferred from land title, tenancy, guardianship, stewardship, data provision, or ecological rights. Affected Indigenous nations and communities retain their lawful rights and benefit-sharing authority. Credits cannot extinguish restoration duties or authorize continued harm elsewhere.</p> <p>The registry records legally effective facts but does not create title, carbon ownership, ecological rights, guardianship, stewardship, permits, sacred status, or tax obligations. Blockchain is optional and cannot override correction, privacy, protected knowledge, lawful deletion, or court orders.</p> <h2>15. Ecological repair, contamination, and liability</h2> <p>The Right to Ecological Repair supports access to restoration knowledge, native seeds, lawful microbial resources, remediation, legal aid, compensation, and corrective action. It does not create an unbounded right to enter land, take samples, compel disclosure, distribute protected cultures, or impose liability without process.</p> <p>Monitoring, inspection, investigation, evidence custody, scientific attribution, liability, judgment, remediation, and physical execution are separate. A sample or model may support an investigation; it is not proof of guilt. Legacy, cumulative, transboundary, public, and current sources must be distinguished, and exculpatory evidence and dissent preserved.</p> <h2>16. Microbial commons, seeds, and anti-patent protection</h2> <p>v3.2 preserves the normative claim that naturally occurring microbial and fungal life should not be enclosed in ways that dispossess communities or impede ecological repair. The framework itself cannot make a patent universally invalid. Competent law may establish exclusions, disclosure duties, prior-art systems, defensive publication, research exceptions, compulsory licences, benefit-sharing, or invalidation routes.</p> <p>No “anti-patent” mechanism may force disclosure of sacred or protected knowledge. Deposit in a seed or microbiome bank does not waive customary law, confidentiality, attribution, benefit sharing, or the right to restrict derivative use. Biosafety, ecological release, quarantine, transport, and cross-border transfer remain separately governed.</p> <h2>17. Future generations and youth participation</h2> <p>Youth delegations and future-generation review retain structural weight through long-horizon analysis, option-preservation review, published dissent, mandatory explanation, reconsideration, and independent review. They do not claim to sovereignly represent all future persons.</p> <p>A binding youth veto exists only if a competent constituting instrument defines its scope, threshold, procedure, conflicts, accessibility, review, override, expiry, and remedy. The source “supermajority veto” therefore becomes a model option rather than a self-executing power.</p> <h2>18. Mental health, culture, and spiritual relationship</h2> <p>Ecopsychological healing, cultural revival, ceremony, language, and spiritual relation can be important parts of land repair. Participation is voluntary and culturally governed. LMCI, spiritual-health measures, ceremony participation, or recognition by cultural guardians cannot affect title, permits, taxes, certification, AUBI, housing, legal credibility, or access to essential services.</p> <p>The Moral Operating System remains an advisory ethical resource. Its developmental, philosophical, or spiritual categories cannot create land authority or classify people for consequential decisions.</p> <h2>19. Emergency soil and food-system protection</h2> <p>Acute contamination, erosion, desertification, salinization, wildfire, flood, crop failure, microbial depletion, or infrastructure collapse may justify an urgent-protection request. The request must identify the competent authority, exact act, affected land and people, alternatives, essential food, water, housing, health, worker, tenant, and Indigenous safeguards, duration, review, expiry, return, compensation, and remedy.</p> <p>Permanent resettlement, land allocation, title change, eviction, receivership, closure, seizure, or force cannot be inferred from the emergency. Migration, housing, Water v5.2, CDEE/ECRC, Hearthstone, CERGTA, and SCPA interfaces remain distinct.</p> <h2>20. Mediation, adjudication, and enforcement</h2> <p>Values-Based Conflict Transformation may support voluntary dialogue over competing land uses. It cannot compel reconciliation, extract evidence, decide title, impose a permit, authenticate sacredness, or become a hidden tribunal. Failure or impasse does not create enforcement authority.</p> <p>A competent court or tribunal independently determines jurisdiction, applicable law, evidence, interim relief, judgment, restoration, compensation, penalty, appeal, and enforcement. Soil institutions may prepare a bounded referral; they cannot predetermine guilt or execute judgment.</p> <p>Search, seizure, eviction, restraint, custody, force, cyber action, border measures, asset freezing, or analogous execution requires CERGTA-48 and separately valid SCPA authority. A soil claim may justify a hearing. It does not authorize a raid.</p> <h2>21. Data, AI, dashboards, and accessibility</h2> <p>AI, satellites, sensors, precision agriculture, laboratory automation, digital twins, blockchain, and scenario tools may assist observation, accessibility, and administration. They cannot automatically define legal boundaries, recognize rights, assign causation, set a tax, issue a permit, block a sale, revoke tenure, classify fraud, declare an emergency, or select an enforcement target.</p> <p>Every consequential record must support low-tech and offline participation, accessible formats, language access, correction, human review, protected-data layers, and an explanation that can be understood by affected people. Digital absence is not evidence of non-compliance or lack of rights.</p> <h2>22. Adoption and implementation pathway</h2> <h3>22.1 Phase 0 — Authority and relationship mapping</h3> <p>Before pilots, identify affected Indigenous nations, applicable law, land and resource jurisdictions, existing Councils and agencies, title and tenure systems, food and housing dependencies, soil baselines, data custodians, emergency authorities, courts, funds, and withheld powers.</p> <h3>22.2 Phase 1 — Knowledge, participation, and voluntary projects</h3> <p>Establish accessible monitoring, protected-knowledge protocols, farmer and worker support, voluntary restoration, seed and microbial safeguards, conflict transformation, and independent correction. No pilot creates regulatory power.</p> <h3>22.3 Phase 2 — Separately enacted standards and programmes</h3> <p>Jurisdictions may adopt standards, grants, permits, tax measures, rights-of-first-refusal, certification, or carbon programmes through exact legal instruments and CERGTA records. Open cases and transition duties are explicitly managed.</p> <h3>22.4 Phase 3 — Interoperable bioregional coordination</h3> <p>Councils and authorities coordinate across watersheds, food systems, biodiversity, oceans, urban areas, and national borders while retaining separate jurisdiction, clocks, data custody, and remedies.</p> <h2>23. Quick-start guide for a Bioregional Land and Food Council</h2> <ol><li><strong>Map authority before ecology:</strong> publish <code>SOIL-01</code>, including powers the Council does not possess.</li> <li><strong>Identify affected nations and interests:</strong> complete <code>SOIL-03</code> and <code>SOIL-04</code> before collecting protected knowledge or proposing land consequences.</li> <li><strong>Establish lawful monitoring:</strong> use <code>SOIL-05</code> through <code>SOIL-08</code>, with low-tech access, sample sovereignty, uncertainty, and correction.</li> <li><strong>Choose a non-coercive first project:</strong> compost, erosion repair, farmer support, urban food growing, seed preservation, or voluntary microbial restoration.</li> <li><strong>Separate ecological verification from payment:</strong> use <code>SOIL-31</code> and a competent AUBI or financial decision.</li> <li><strong>Use conflict transformation without hidden adjudication:</strong> keep mediation voluntary and preserve independent legal routes.</li> <li><strong>Record all non-activated powers:</strong> use <code>SOIL-48</code> for targets, certification tiers, pilot claims, and future ambitions.</li></ol> <h2>24. CERGTA inheritance and common record rules</h2> <p>Every consequential Soil record contains or inherits the forty-field <code>CERGTA/0.1</code> common header. A local record may specialize a CERGTA record but may not erase its canonical identity, weaken safeguards, merge distinct powers, or convert transport into authority.</p> <h3>24.1 Forty inherited header fields</h3> <ol><li><code>record_id</code></li> <li><code>record_instance_id</code></li> <li><code>record_version</code></li> <li><code>status</code></li> <li><code>created_at</code></li> <li><code>effective_at</code></li> <li><code>created_by</code></li> <li><code>competent_authority</code></li> <li><code>legal_source</code></li> <li><code>jurisdiction</code></li> <li><code>authority_activation_state</code></li> <li><code>ecological_action_cluster_id</code></li> <li><code>action_class</code></li> <li><code>exact_act</code></li> <li><code>entity_asset_resource_id</code></li> <li><code>ecological_and_legal_boundary_version</code></li> <li><code>affected_persons_and_communities</code></li> <li><code>affected_indigenous_nations</code></li> <li><code>claimants_and_interest_holders</code></li> <li><code>linked_records</code></li> <li><code>source_and_reliability_limits</code></li> <li><code>uncertainty_and_dissent</code></li> <li><code>prohibited_inferences</code></li> <li><code>rights_and_safeguards</code></li> <li><code>essential_minimums</code></li> <li><code>consent_fpic_and_nonengagement_status</code></li> <li><code>access_class</code></li> <li><code>notice_status</code></li> <li><code>review_authority</code></li> <li><code>review_due_at</code></li> <li><code>expires_at_or_nonexpiry_basis</code></li> <li><code>challenge_and_interim_relief_route</code></li> <li><code>termination_trigger</code></li> <li><code>authority_asset_and_credential_return</code></li> <li><code>data_disposition_rule</code></li> <li><code>remedy_route</code></li> <li><code>supersedes</code></li> <li><code>superseded_by</code></li> <li><code>integrity_digest</code></li> <li><code>public_summary_or_protected_basis</code></li></ol> <h3>24.2 Access classes</h3> <ul><li><code>CERGTA-PUBLIC</code></li> <li><code>CERGTA-AFFECTED</code></li> <li><code>CERGTA-CLAIMANT</code></li> <li><code>CERGTA-REVIEW</code></li> <li><code>CERGTA-OPERATIONAL</code></li> <li><code>CERGTA-PROTECTED</code></li> <li><code>CERGTA-INDIGENOUS-RESTRICTED</code></li></ul> <h3>24.3 Handoff states</h3> <p><code>offered</code>, <code>received_not_assessed</code>, <code>deficient</code>, <code>partially_accepted</code>, <code>accepted</code>, <code>concurrent_responsibility</code>, <code>rejected</code>, <code>withdrawn</code>, <code>returned</code>, <code>closed</code>.</p> <p>Silence is never acceptance. Partial acceptance must specify which records and responsibilities were accepted. The sender ordinarily retains duties until the recipient explicitly accepts them or the governing law supplies another result.</p> <h3>24.4 Lifecycle states</h3> <p><code>draft</code>, <code>submitted</code>, <code>advisory</code>, <code>authorized</code>, <code>partially_authorized</code>, <code>active</code>, <code>suspended</code>, <code>expired</code>, <code>terminated</code>, <code>under_review</code>, <code>corrected</code>, <code>superseded</code>, <code>archived</code>, <code>handoff_pending</code>, <code>authority_return_pending</code>, <code>remedy_pending</code>, <code>data_disposition_pending</code>, <code>closed</code>.</p> <p>Operational completion is not legal closure. A record cannot become <code>closed</code> while authority return, release, correction, registry repair, restoration, compensation, sample or data disposition, service continuity, or remedy remains pending.</p> <h3>24.5 Adoption states</h3> <p><code>proposed</code>, <code>advisory</code>, <code>voluntarily_adopted</code>, <code>contractually_binding</code>, <code>enacted</code>, <code>treaty_active</code>, <code>suspended</code>, <code>expired</code>, <code>terminated</code>.</p> <h2>25. Canonical Soil record catalogue</h2> <p>The following local records implement the Soil-specific layer. Their local names do not replace the controlling CERGTA identity, and each record inherits the forty CERGTA common header fields of §24.1.</p> <p><strong>Minimum rule for every record below.</strong> A record creates no authority beyond the exact constituting instrument named in its inherited CERGTA header. Prohibited inferences and linked-record requirements remain active regardless of how the record is packaged, extended, split, or displayed.</p> <table><thead><tr><th>ID</th><th>Record</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SOIL-01</code></td><td>Constituting Instrument, Jurisdiction, Adoption, and Land-Power Register</td><td>Pins the exact law, charter, delegation, territorial and subject-matter jurisdiction, adoption state, activated functions, withheld powers, review, expiry, succession, and authority return.</td></tr><tr><td><code>SOIL-02</code></td><td>Soil System, Land Parcel, Landscape, and Relational-Boundary Intake</td><td>Describes the soil system, parcel, landscape, watershed connections, subsoil, microbial communities, land uses, sacred relations, existing legal boundaries, uncertainty, and transboundary effects without creating title or jurisdiction.</td></tr><tr><td><code>SOIL-03</code></td><td>Affected Indigenous Nations, Communities, Residents, Workers, and Users Map</td><td>Identifies affected Indigenous nations, customary users, residents, tenants, landless people, farmers, workers, food systems, neighbours, creditors, and other interests without deciding representation or priority.</td></tr><tr><td><code>SOIL-04</code></td><td>Title, Tenure, Customary Use, Lease, Covenant, and Encumbrance Baseline</td><td>Records present title and tenure, customary and occupancy rights, leases, mortgages, easements, licences, public obligations, environmental covenants, disputes, and missing or contested evidence.</td></tr><tr><td><code>SOIL-05</code></td><td>Soil and Microbial Observation, Sampling, and Provenance Record</td><td>Records sampling purpose, location, method, collector, custody, calibration, limitations, community observations, sensor outputs, laboratory results, and correction history.</td></tr><tr><td><code>SOIL-06</code></td><td>Traditional Knowledge, Sacred Knowledge, Sample Sovereignty, and Access Record</td><td>Records the affected nation or knowledge holder, permitted purpose, access class, attribution, benefit-sharing, non-disclosure, derivative-use restrictions, sample return or destruction, and refusal without adverse inference.</td></tr><tr><td><code>SOIL-07</code></td><td>Indicator, Threshold, Weighting, and Model Specification</td><td>Defines soil organic matter, carbon, nutrient density, microbial diversity, fungal health, water retention, contamination, social and cultural indicators, baselines, weights, uncertainty, missing data, and prohibited uses.</td></tr><tr><td><code>SOIL-08</code></td><td>Soil Interpretation, Causal Attribution, Counterfactual, and Uncertainty Record</td><td>Separates observed condition from causal hypotheses, inherited degradation, external shocks, management contribution, alternative explanations, dissent, confidence, and need for further study.</td></tr><tr><td><code>SOIL-09</code></td><td>Advisory Soil Alert, Review Recommendation, and Non-Activation Record</td><td>Allows an evidence-based alert or recommendation while stating that no right, permit, tax, payment, sale restriction, tenure consequence, emergency power, or enforcement authority follows automatically.</td></tr><tr><td><code>SOIL-10</code></td><td>Soil or Landscape Rights Petition and Standing Record</td><td>Records who seeks legal recognition for a soil system, landscape, microbial commons, or related ecological entity, the proposed rights, evidence, affected interests, desired relief, and controlling legal route.</td></tr><tr><td><code>SOIL-11</code></td><td>Rights Review Recommendation, Dissent, and Referral Record</td><td>Provides an advisory recommendation on ecological rights, including minority views, conflicts, non-derogable human and Indigenous rights, boundary uncertainty, and the competent recognition authority.</td></tr><tr><td><code>SOIL-12</code></td><td>Lawful Soil or Landscape Rights Recognition Link</td><td>References a separately competent CERGTA-13 decision and records the recognized entity, rights catalogue, boundary, jurisdiction, effective date, review, conflict rules, and non-title effect.</td></tr><tr><td><code>SOIL-13</code></td><td>Guardian Nomination, Appointment, Mandate, and Fiduciary-Duty Link</td><td>Links nomination and lawful appointment, standing, affected-nation instructions, conflicts, prohibited acts, budget, reporting, complaints, removal, liability, term, and succession.</td></tr><tr><td><code>SOIL-14</code></td><td>Sacred, Biocultural, Living-Culture, and Restricted-Site Relation Record</td><td>Separates internal cultural recognition, confidentiality, access restrictions, external legal recognition, land-use implications, and title effects; no external body may authenticate sacredness for an affected nation.</td></tr><tr><td><code>SOIL-15</code></td><td>Land, Rematriation, Restitution, and Competing-Claim Intake</td><td>Records requested relief and competing historical, customary, occupancy, reparative, ecological, public, and private claims, with anti-extinguishment, interim non-prejudice, and affected-nation control.</td></tr><tr><td><code>SOIL-16</code></td><td>Hearthstone Claims, Title, Trust, and Rematriation Handoff</td><td>Routes title, conveyance, voluntary conversion, community land trust, rematriation, compensation, debt, tenant, worker, registry, receivership, succession, and dissolution matters to Hearthstone v2.0 and competent law.</td></tr><tr><td><code>SOIL-17</code></td><td>Bioregional Land and Food Council Charter and Functional-Separation Record</td><td>Defines the Council’s lawful planning, participation, technical-support, grant, regulatory, inspection, or administrative functions; separates them from guardianship, utility operation, adjudication, fund custody, title, and enforcement.</td></tr><tr><td><code>SOIL-18</code></td><td>Land-Use Plan, Zoning Proposal, Adoption, and Review Record</td><td>Records plan evidence, alternatives, affected interests, food and housing effects, ecological objectives, adoption state, competent authority, review, amendment, expiry, and remedy.</td></tr><tr><td><code>SOIL-19</code></td><td>Minimum Regenerative Standard and Practice Specification</td><td>Defines soil-cover, disturbance, roots, diversity, livestock, nutrient, synthetic-input, erosion, microbial, water, and biodiversity standards, evidence quality, regional adaptation, adoption state, transition period, and exceptions.</td></tr><tr><td><code>SOIL-20</code></td><td>Soil-Degrading Chemical or Practice Restriction Decision</td><td>Records the competent authority, substance or practice, evidence, affected users and workers, alternatives, transition support, proportionality, duration, review, expiry, correction, and appeal.</td></tr><tr><td><code>SOIL-21</code></td><td>Land-Use Permit, Licence, Variance, and Condition Decision</td><td>Records applicant, parcel, activity, conditions, monitoring, protected rights, duration, transferability, review, amendment, suspension, expiry, and remedy.</td></tr><tr><td><code>SOIL-22</code></td><td>Nutrient, Contaminant, Extraction, Irrigation, or Disturbance Cap Decision</td><td>Records the lawful cap or quota, method, essential food and water needs, ecological reserve, uncertainty, allocation, exceptions, duration, review, and correction.</td></tr><tr><td><code>SOIL-23</code></td><td>Land-Value, Anti-Speculation, Soil-Harm, or Other Levy Decision</td><td>Records the tax or levy authority, valuation base, liable person, exemptions, Indigenous and customary protections, housing and farm effects, hardship, use of revenue, notice, appeal, review, and expiry.</td></tr><tr><td><code>SOIL-24</code></td><td>Proposed Sale, Right of First Refusal, and Transaction-Review Record</td><td>Records notice, legally eligible holders, valuation, financing, timelines, competing claims, tenants, workers, public services, anti-circumvention, decision, review, and completion or release.</td></tr><tr><td><code>SOIL-25</code></td><td>Community Objection, Temporary Pause, and Sale-Restriction Decision</td><td>Separates community objection and reconsideration from any binding sale restriction; a restriction requires exact enacted authority, scope, duration, valuation, compensation where due, independent review, and remedy.</td></tr><tr><td><code>SOIL-26</code></td><td>Generational Stewardship Lease or Land-Relation Charter</td><td>Defines the legal interest, term, rent or contribution, regenerative duties, housing and livelihood rights, maintenance, investment, succession, transfer, default, cure, termination, compensation, and final land disposition.</td></tr><tr><td><code>SOIL-27</code></td><td>Community Land Trust, Food Commons, Housing, and Shared-Infrastructure Interface</td><td>Records the relationship between land title, trust or public ownership, housing, farms, common facilities, governance, beneficiaries, affordability, service continuity, finance, and Hearthstone registry links.</td></tr><tr><td><code>SOIL-28</code></td><td>Stewardship Plan, Budget, Participation, and External-Shock Baseline</td><td>Records ecological objectives, current condition, inherited harm, external dependencies, duties, budget, workers, tenants, affected-nation participation, monitoring, contingency plans, and no-fault factors.</td></tr><tr><td><code>SOIL-29</code></td><td>Stewardship Performance, Support, Correction, Suspension, and Succession Record</td><td>Separates metric review from consequence and records context, gaming risk, support, notice, correction plan, independent verification, interim relief, suspension or succession authority, appeal, and remedy.</td></tr><tr><td><code>SOIL-30</code></td><td>Regenerative Agriculture Fund, Grant, Subsidy, Insurance, and Procurement Decision</td><td>Records lawful finance authority, applicant, eligibility, amount, conditions, risk allocation, procurement, conflicts, worker and community effects, audit, correction, clawback limits, expiry, and appeal.</td></tr><tr><td><code>SOIL-31</code></td><td>AUBI Ecological Contribution Verification and Financial Handoff</td><td>Verifies the ecological activity and evidence, then routes a separate eligibility and payment decision to AUBI or another competent financial authority; verification is not a payment order or fraud finding.</td></tr><tr><td><code>SOIL-32</code></td><td>Soil, Nutrient, Microbial, and Regenerative Certification Decision</td><td>Records method, applicant, product or operation, evidence, audit, tier, scope, expiry, surveillance, correction, suspension, appeal, and the rule that certification is not a permit or market restriction.</td></tr><tr><td><code>SOIL-33</code></td><td>Digital Product Passport Publication, Correction, and Use-Limitation Record</td><td>Records the exact claim, source, version, uncertainty, access, permitted uses, correction propagation, expiry, and prohibition on automatic adverse action from a passport score.</td></tr><tr><td><code>SOIL-34</code></td><td>Soil Carbon and Ecosystem-Service Methodology Record</td><td>Defines additionality, permanence, leakage, uncertainty, baseline, soil depth, microbial contribution, reversal risk, Indigenous and community rights, double-counting controls, and prohibited title inference.</td></tr><tr><td><code>SOIL-35</code></td><td>Soil Carbon Credit, Benefit, Issuance, Transfer, and Retirement Decision</td><td>Records the competent registry or financial authority, verified quantity, ownership or benefit claim, affected-nation consent, revenue sharing, issuance, transfer, retirement, reversal buffer, correction, and remedy.</td></tr><tr><td><code>SOIL-36</code></td><td>Soil, Stewardship, Carbon, Permit, and Rights Registry Entry and Correction</td><td>Records a legally effective fact without creating it; supports paper and digital access, identity and boundary correction, privacy, protected knowledge, deletion where lawful, audit history, and non-constitutive status.</td></tr><tr><td><code>SOIL-37</code></td><td>Inspection Authorization, Entry, Sampling, Biosecurity, and Report Record</td><td>Records authority, purpose, place, notice, consent or warrant, scope, safety, sample handling, biosecurity, private and sacred areas, findings, correction, closure, and remedy.</td></tr><tr><td><code>SOIL-38</code></td><td>Soil-Harm Investigation Opening, Methods, Parties, and Evidence Custody</td><td>Separates monitoring from legal investigation and records jurisdiction, allegation, methods, parties, exculpatory evidence, laboratory and sample custody, disclosure, duration, closure, and referral.</td></tr><tr><td><code>SOIL-39</code></td><td>Scientific Attribution, Liability Recommendation, and Dissent Record</td><td>Records causal evidence, responsible-actor hypotheses, confidence, alternatives, legacy contamination, cumulative and transboundary causes, dissent, and the rule that attribution does not itself establish liability or guilt.</td></tr><tr><td><code>SOIL-40</code></td><td>Urgent Soil, Food-System, or Contamination Protection Request</td><td>Requests a least-restrictive, time-limited CERGTA-42 action based on individualized evidence, alternatives, essential food and housing safeguards, affected-nation authority, review, expiry, compensation, and remedy.</td></tr><tr><td><code>SOIL-41</code></td><td>Temporary Land or Soil Administration and Hearthstone Receivership Handoff</td><td>Routes any proposed temporary administration or receivership to CERGTA-43, Hearthstone v2.0, and competent law; records exact assets, powers, conflicts, services, workers, tenants, review, expiry, return, and compensation.</td></tr><tr><td><code>SOIL-42</code></td><td>Soil Emergency Assistance Mission and CDEE/ECRC Interface</td><td>Records an accepted civilian technical mission for assessment, remediation support, seed or culture preservation, food-system continuity, logistics, and recovery under competent emergency command without independent coercive power.</td></tr><tr><td><code>SOIL-43</code></td><td>Ecological Repair, Remediation, Requalification, and Verification Record</td><td>Records the lawful restoration or corrective plan, responsible authority or party, affected people, standards, methods, funding, worker safety, verification, adaptive revision, completion, residual harm, and long-term custody.</td></tr><tr><td><code>SOIL-44</code></td><td>Compensation, Reparations, Transition Support, and Benefit-Sharing Record</td><td>Records eligible claimants, legal source, valuation, tenant and worker support, livelihood transition, Indigenous reparations, benefit-sharing, payment authority, timing, tax and debt effects, correction, appeal, and unresolved duties.</td></tr><tr><td><code>SOIL-45</code></td><td>Mediation, Adjudication, Judgment, and Reasons Handoff</td><td>Separates voluntary Values-Based Conflict Transformation from binding adjudication and records the competent forum, parties, issues, evidence, interim relief, reasons, remedy, appeal, and enforcement status.</td></tr><tr><td><code>SOIL-46</code></td><td>Enforcement Request, Acceptance, Execution, and SCPA Interface</td><td>Records any request for search, seizure, closure, asset action, restraint, custody, force, cyber action, border measure, or analogous execution; no Soil institution receives execution power through referral.</td></tr><tr><td><code>SOIL-47</code></td><td>Authority Expiry, Termination, Return, Data Disposition, and Unresolved-Duty Custody</td><td>Ends permits, missions, grants, restrictions, mandates, appointments, and delegated powers; returns authority and assets while preserving claims, restoration, compensation, correction, service, and protected-data duties without residual command.</td></tr><tr><td><code>SOIL-48</code></td><td>Pilot, Sandbox, Target, Certification, and Power Non-Activation Register</td><td>Records that pilots, targets, dashboard scores, future dates, certification tiers, coalition size, BAZ readiness, or framework labels do not activate rights, title, taxation, restrictions, receivership, or enforcement.</td></tr></tbody></table> <h2>26. Complete CERGTA crosswalk</h2> <p>Every row carries the same default boundary, stated once here rather than restated forty-five times: <strong>Soil v3.2 preserves the canonical identity and boundary of each CERGTA record and routes any consequence through the named local record and its competent authority.</strong> The table’s content is the class, the relationship type, and the record mapping. Rows that carry a boundary <em>beyond</em> the default are listed under §26.1.</p> <table><thead><tr><th>CERGTA record</th><th>Canonical title</th><th align="right">Class</th><th>Relationship</th><th>Soil record(s)</th></tr></thead><tbody><tr><td><code>CERGTA-01</code></td><td>Constituting Instrument, Legal Source, Jurisdiction, and Activation Status</td><td align="right">A</td><td>implements</td><td><code>SOIL-01</code></td></tr><tr><td><code>CERGTA-02</code></td><td>Ecological Entity Candidate, Resource, Asset, and Boundary Intake</td><td align="right">A</td><td>implements</td><td><code>SOIL-02</code></td></tr><tr><td><code>CERGTA-03</code></td><td>Observation, Monitoring, Sampling, and Provenance Record</td><td align="right">A</td><td>implements</td><td><code>SOIL-05</code></td></tr><tr><td><code>CERGTA-04</code></td><td>Ecological Data Purpose, Consent, Sovereignty, Access, and Retention Record</td><td align="right">A</td><td>implements</td><td><code>SOIL-06</code></td></tr><tr><td><code>CERGTA-05</code></td><td>Indicator, Index, Threshold, Weighting, and Model Specification</td><td align="right">B</td><td>implements</td><td><code>SOIL-07</code></td></tr><tr><td><code>CERGTA-06</code></td><td>Ecological Interpretation, Causal Assessment, and Uncertainty Record</td><td align="right">B</td><td>implements</td><td><code>SOIL-08</code></td></tr><tr><td><code>CERGTA-07</code></td><td>Traditional Knowledge, Sacred Knowledge, and Epistemic Contribution Record</td><td align="right">B</td><td>implements</td><td><code>SOIL-06</code></td></tr><tr><td><code>CERGTA-08</code></td><td>Affected Persons, Communities, Nations, Users, Workers, and Rights Map</td><td align="right">A</td><td>implements</td><td><code>SOIL-03</code></td></tr><tr><td><code>CERGTA-09</code></td><td>Affected Indigenous Nation and Applicable-Law Determination</td><td align="right">F</td><td>implements</td><td><code>SOIL-03</code></td></tr><tr><td><code>CERGTA-10</code></td><td>Notice, Participation, Accessibility, Counsel, and Support Record</td><td align="right">A</td><td>implements</td><td><code>SOIL-03</code></td></tr><tr><td><code>CERGTA-11</code></td><td>Ecological Rights Review Petition and Standing Record</td><td align="right">C</td><td>implements</td><td><code>SOIL-10</code></td></tr><tr><td><code>CERGTA-12</code></td><td>Rights Review Recommendation and Dissent Record</td><td align="right">C</td><td>implements</td><td><code>SOIL-11</code></td></tr><tr><td><code>CERGTA-13</code></td><td>Lawful Ecological Rights Recognition Decision</td><td align="right">D</td><td>imports / links</td><td><code>SOIL-12</code></td></tr><tr><td><code>CERGTA-14</code></td><td>Rights Catalogue, Priority, Conflict, and Non-Derogation Record</td><td align="right">D</td><td>implements</td><td><code>SOIL-12</code></td></tr><tr><td><code>CERGTA-15</code></td><td>Ecological and Legal Boundary Constitution Record</td><td align="right">D</td><td>implements</td><td><code>SOIL-02, SOIL-12</code></td></tr><tr><td><code>CERGTA-16</code></td><td>Guardian Nomination and Eligibility Record</td><td align="right">E</td><td>implements</td><td><code>SOIL-13</code></td></tr><tr><td><code>CERGTA-17</code></td><td>Guardian Appointment, Mandate, and Standing Record</td><td align="right">E</td><td>imports / links</td><td><code>SOIL-13</code></td></tr><tr><td><code>CERGTA-18</code></td><td>Guardian Fiduciary Duty, Instructions, Conflict, and Recusal Record</td><td align="right">E</td><td>implements</td><td><code>SOIL-13</code></td></tr><tr><td><code>CERGTA-19</code></td><td>Guardian Review, Complaint, Removal, Substitution, and Liability Record</td><td align="right">E</td><td>implements</td><td><code>SOIL-13</code></td></tr><tr><td><code>CERGTA-20</code></td><td>Sacred, Cultural, Biocultural, and Inalienability Designation Petition</td><td align="right">F</td><td>implements</td><td><code>SOIL-14</code></td></tr><tr><td><code>CERGTA-21</code></td><td>Sacred, Cultural, Biocultural, and Inalienability Designation Decision</td><td align="right">F</td><td>imports / links</td><td><code>SOIL-14</code></td></tr><tr><td><code>CERGTA-22</code></td><td>Claim Intake, Standing, and Relief Requested Record</td><td align="right">G</td><td>implements</td><td><code>SOIL-15</code></td></tr><tr><td><code>CERGTA-23</code></td><td>Competing Claims, Parties, Interests, and Non-Extinguishment Map</td><td align="right">G</td><td>implements</td><td><code>SOIL-15</code></td></tr><tr><td><code>CERGTA-24</code></td><td>Historical, Customary, Occupancy, Use, and Documentary Evidence Record</td><td align="right">G</td><td>implements</td><td><code>SOIL-04, SOIL-15</code></td></tr><tr><td><code>CERGTA-25</code></td><td>Interim Non-Prejudice and Anti-Dissipation Protection Record</td><td align="right">G</td><td>implements</td><td><code>SOIL-15, SOIL-40</code></td></tr><tr><td><code>CERGTA-26</code></td><td>Title, Tenure, Trust, Covenant, Licence, and Encumbrance Baseline Record</td><td align="right">H</td><td>implements</td><td><code>SOIL-04</code></td></tr><tr><td><code>CERGTA-27</code></td><td>Transfer, Rematriation, Trust Constitution, and Conveyance Authorization</td><td align="right">H</td><td>imports / links</td><td><code>SOIL-16</code></td></tr><tr><td><code>CERGTA-28</code></td><td>Compensation, Reparations, Debt, Tenant, Worker, User, and Service Continuity Record</td><td align="right">H</td><td>implements</td><td><code>SOIL-16, SOIL-44</code></td></tr><tr><td><code>CERGTA-29</code></td><td>Commons, Title, Rights, Guardian, Permit, and Stewardship Registry Entry</td><td align="right">H</td><td>implements</td><td><code>SOIL-36</code></td></tr><tr><td><code>CERGTA-30</code></td><td>Registry Error, Identity Collision, Boundary Conflict, and Correction Record</td><td align="right">H</td><td>implements</td><td><code>SOIL-36</code></td></tr><tr><td><code>CERGTA-31</code></td><td>Stewardship Charter, Purpose, Powers, Duties, and Prohibited Acts</td><td align="right">I</td><td>implements</td><td><code>SOIL-26, SOIL-27</code></td></tr><tr><td><code>CERGTA-32</code></td><td>Stewardship Plan, Ecological Objective, Budget, and Participation Record</td><td align="right">I</td><td>implements</td><td><code>SOIL-28</code></td></tr><tr><td><code>CERGTA-33</code></td><td>Stewardship Performance, Audit, Metric-Gaming, and Context Record</td><td align="right">I</td><td>implements</td><td><code>SOIL-28, SOIL-29</code></td></tr><tr><td><code>CERGTA-34</code></td><td>Stewardship Correction, Suspension, Revocation, Succession, and Dissolution Record</td><td align="right">I</td><td>implements</td><td><code>SOIL-29, SOIL-41</code></td></tr><tr><td><code>CERGTA-35</code></td><td>Ecological Standard, Target, Plan, and Legal Adoption Status Record</td><td align="right">J</td><td>implements</td><td><code>SOIL-18, SOIL-19</code></td></tr><tr><td><code>CERGTA-36</code></td><td>Resource Priority, Essential Minimum, Allocation Method, and Scarcity Record</td><td align="right">K</td><td>implements</td><td><code>SOIL-22</code></td></tr><tr><td><code>CERGTA-37</code></td><td>Quota, Permit, Licence, Tariff, Bond, and Use-Condition Decision</td><td align="right">K</td><td>implements</td><td><code>SOIL-20, SOIL-21, SOIL-22, SOIL-23</code></td></tr><tr><td><code>CERGTA-38</code></td><td>Commercial Restriction, Service Continuity, and Non-Deprivation Record</td><td align="right">K</td><td>implements</td><td><code>SOIL-24, SOIL-25</code></td></tr><tr><td><code>CERGTA-39</code></td><td>Inspection Authorization, Entry, Sampling, and Report Record</td><td align="right">L</td><td>implements</td><td><code>SOIL-37</code></td></tr><tr><td><code>CERGTA-40</code></td><td>Ecological Investigation Opening, Methods, Parties, and Closure Record</td><td align="right">L</td><td>implements</td><td><code>SOIL-38</code></td></tr><tr><td><code>CERGTA-41</code></td><td>Ecological Evidence Custody, Scientific Attribution, and Admissibility Record</td><td align="right">L</td><td>implements</td><td><code>SOIL-38, SOIL-39</code></td></tr><tr><td><code>CERGTA-42</code></td><td>Urgent Ecological Protection Authorization</td><td align="right">M</td><td>implements</td><td><code>SOIL-40</code></td></tr><tr><td><code>CERGTA-43</code></td><td>Temporary Ecological Receivership and Administration Record</td><td align="right">N</td><td>imports / links</td><td><code>SOIL-41</code></td></tr><tr><td><code>CERGTA-44</code></td><td>Port, Market, Procurement, Certification, Listing, and Delisting Restriction Record</td><td align="right">N</td><td>implements</td><td><code>SOIL-32, SOIL-33</code></td></tr><tr><td><code>CERGTA-45</code></td><td>Ecological Tax, Tariff, Levy, Bond, Subsidy, and Funding Decision</td><td align="right">O</td><td>implements</td><td><code>SOIL-23, SOIL-30</code></td></tr><tr><td><code>CERGTA-46</code></td><td>Freeze, Escrow, Forfeiture, Redistribution, Reparations, and Compensation Fund Record</td><td align="right">O</td><td>implements</td><td><code>SOIL-35, SOIL-44</code></td></tr><tr><td><code>CERGTA-47</code></td><td>Ecological and Commons Adjudication, Judgment, and Reasons Record</td><td align="right">P</td><td>imports / links</td><td><code>SOIL-45</code></td></tr><tr><td><code>CERGTA-48</code></td><td>Enforcement Request, Acceptance, Execution, and SCPA Interface Record</td><td align="right">P</td><td>imports / links</td><td><code>SOIL-46</code></td></tr><tr><td><code>CERGTA-49</code></td><td>Ecological Restoration, Corrective Action, Requalification, and Verification Record</td><td align="right">Q</td><td>implements</td><td><code>SOIL-43</code></td></tr><tr><td><code>CERGTA-50</code></td><td>Appeal, Interim Relief, Complaint, Correction, Restitution, and Compensation Record</td><td align="right">Q</td><td>implements</td><td><code>SOIL-29, SOIL-36, SOIL-44, SOIL-45</code></td></tr><tr><td><code>CERGTA-51</code></td><td>Authority Expiry, Termination, Return, Succession, and Dissolution Record</td><td align="right">R</td><td>implements</td><td><code>SOIL-47</code></td></tr><tr><td><code>CERGTA-52</code></td><td>Data Return, Deletion, Archive, Public Memory, and Protected-Knowledge Disposition Record</td><td align="right">R</td><td>implements</td><td><code>SOIL-47</code></td></tr><tr><td><code>CERGTA-53</code></td><td>Unresolved Claim, Harm, Restoration, Service, and Duty Custody Record</td><td align="right">R</td><td>implements</td><td><code>SOIL-47</code></td></tr><tr><td><code>CERGTA-54</code></td><td>Ecological and Commons Power Non-Activation, Pilot, and Sandbox Register</td><td align="right">R</td><td>implements</td><td><code>SOIL-48</code></td></tr></tbody></table> <h3>26.1 Rows with a boundary beyond the default</h3> <ul><li><strong><code>CERGTA-13</code></strong> — Only a separately competent legal authority may recognize soil or landscape rights.</li> <li><strong><code>CERGTA-20</code></strong> — Sacred and biocultural relations are controlled by the affected nation; a Soil Council cannot authenticate sacredness for another people.</li> <li><strong><code>CERGTA-27</code></strong> — Title, rematriation, conveyance, trust constitution, and compensation route through Hearthstone v2.0 and competent law.</li> <li><strong><code>CERGTA-34</code></strong> — A score cannot suspend or revoke stewardship; due process, no-fault context, support, review, and succession are required.</li> <li><strong><code>CERGTA-37</code></strong> — Standards, permits, caps, taxes, and use conditions remain distinct decisions.</li> <li><strong><code>CERGTA-38</code></strong> — A community objection is not a self-executing veto or sale prohibition.</li> <li><strong><code>CERGTA-43</code></strong> — Receivership is external, temporary, reviewable, automatically expiring, and tied to return and compensation.</li> <li><strong><code>CERGTA-44</code></strong> — Certification and passport data do not themselves create market exclusion or procurement denial.</li> <li><strong><code>CERGTA-48</code></strong> — Coercive execution requires separate SCPA authority; referral does not transfer power.</li></ul> <h2>27. Constitutional readiness gates</h2> <table><thead><tr><th>Gate</th><th>Title</th><th>Pass condition</th></tr></thead><tbody><tr><td>G01</td><td>Exact legal source and land jurisdiction</td><td>Every Council, monitor, fund, permit authority, tax authority, inspector, guardian, emergency actor, registry, adjudicator, and enforcement recipient identifies exact current authority, territory, subject matter, expiry, and remedy.</td></tr><tr><td>G02</td><td>Observation–consequence separation</td><td>Samples, sensors, satellite data, citizen reports, TEK, dashboards, certificates, and scores cannot directly create rights, taxes, permits, sale restrictions, title consequences, payments, or sanctions.</td></tr><tr><td>G03</td><td>EIOI methodological custody</td><td>Soil methods, indicators, thresholds, models, and uncertainty conform to EIOI v2.7 or an equally bounded lawful method process.</td></tr><tr><td>G04</td><td>Affected-nation authority</td><td>The specific affected Indigenous nation determines representation, law, FPIC, sacred knowledge, samples, land relation, and participation; no global proxy substitutes.</td></tr><tr><td>G05</td><td>Protected-knowledge and sample sovereignty</td><td>TEK, sacred knowledge, microbial cultures, genetic material, and samples are purpose-limited, access-controlled, returnable or destructible, and never forced into an open commons.</td></tr><tr><td>G06</td><td>Rights–title separation</td><td>Soil or landscape rights recognition does not transfer land, subsoil, infrastructure, licences, concessions, carbon claims, or regulatory jurisdiction.</td></tr><tr><td>G07</td><td>Guardian–regulator separation</td><td>A guardian represents a recognized entity but does not own land, issue permits, levy taxes, inspect, adjudicate, or command enforcement.</td></tr><tr><td>G08</td><td>Hearthstone title interface</td><td>Claims, title, tenure, trusts, rematriation, voluntary conversion, receivership, succession, and dissolution route through Hearthstone v2.0 and competent law.</td></tr><tr><td>G09</td><td>Competing claims and non-extinguishment</td><td>Indigenous, customary, occupancy, tenant, worker, landless, public, creditor, ecological, and reparative claims are mapped and cannot be erased by registry, score, pilot, or council vote.</td></tr><tr><td>G10</td><td>Council functional separation</td><td>Bioregional Land and Food Councils separate planning, regulatory, inspection, grant, guardian, fund, registry, adjudication, and enforcement functions.</td></tr><tr><td>G11</td><td>Planning adoption state</td><td>A land-use plan or regenerative standard is advisory until adopted by a competent authority; targets, diagrams, or future dates do not activate it.</td></tr><tr><td>G12</td><td>No automatic regenerative mandate</td><td>Minimum regenerative thresholds may guide planning and review but cannot automatically amend permits, leases, title, taxes, subsidies, or criminal liability.</td></tr><tr><td>G13</td><td>Chemical restriction due process</td><td>Restrictions identify authority, evidence, alternatives, transition support, food and worker effects, review, expiry, and appeal.</td></tr><tr><td>G14</td><td>Permit and cap individuality</td><td>Permits, nutrient caps, extraction limits, irrigation conditions, and disturbance controls are separate, individualized, time-limited decisions.</td></tr><tr><td>G15</td><td>Tax and valuation legality</td><td>Land-value or soil-harm taxes require enacted authority, a defined base, notice, hardship and equity rules, valuation challenge, revenue custody, review, and expiry.</td></tr><tr><td>G16</td><td>Right of first refusal constitution</td><td>A proposed sale follows a lawful notice, eligibility, valuation, finance, timeline, anti-circumvention, completion, release, and appeal route.</td></tr><tr><td>G17</td><td>No unbounded community veto</td><td>Community and youth objections trigger explanation, reconsideration, pause where law permits, and review; binding restrictions require exact enacted authority and remedy.</td></tr><tr><td>G18</td><td>Stewardship lease completeness</td><td>Generational leases specify legal interest, housing and livelihood rights, investment, succession, default, cure, termination, compensation, and final disposition.</td></tr><tr><td>G19</td><td>Metric–stewardship separation</td><td>BHI, LMCI, Soil Health Scores, Love Ledger, certification tiers, or microbial indicators may trigger review but cannot automatically revoke tenure, replace stewards, or freeze benefits.</td></tr><tr><td>G20</td><td>No-fault context and support</td><td>Wildfire, drought, war, upstream pollution, inherited contamination, climate shocks, and market disruptions are separated from stewardship breach before consequence.</td></tr><tr><td>G21</td><td>Finance separation and appeal</td><td>Grants, subsidies, insurance, procurement, AUBI, credits, and clawbacks are separate financial decisions with conflicts controls, correction, and appeal.</td></tr><tr><td>G22</td><td>Certification–market separation</td><td>Certification or a Digital Product Passport is not a permit, trade restriction, procurement exclusion, fraud finding, or proof of liability.</td></tr><tr><td>G23</td><td>Carbon-credit integrity and non-title</td><td>Soil-carbon methodology, ownership or benefit, issuance, transfer, retirement, reversal, double counting, Indigenous rights, and land title remain separate.</td></tr><tr><td>G24</td><td>Registry non-constitution</td><td>The registry records effective facts but does not create rights, title, tenure, guardianship, permits, carbon ownership, sacredness, or stewardship authority.</td></tr><tr><td>G25</td><td>Inspection–investigation separation</td><td>Monitoring, inspection, investigation, evidence custody, scientific attribution, liability, adjudication, and execution remain distinct.</td></tr><tr><td>G26</td><td>Microbiome and living-culture safeguards</td><td>Open access never overrides affected-nation authority, biosafety, provenance, benefit sharing, privacy, patent law, sample return, or the right to withhold knowledge.</td></tr><tr><td>G27</td><td>Urgent protection fail-closed</td><td>Severe contamination or erosion may trigger a CERGTA-42 request; no automatic closure, land allocation, eviction, receivership, fund release, or force follows.</td></tr><tr><td>G28</td><td>Emergency command external</td><td>Soil Emergency Assistance Missions operate under CDEE/ECRC and cannot independently allocate resettlement land, create checkpoints, collect intelligence, detain, search, or use force.</td></tr><tr><td>G29</td><td>Mediation–adjudication separation</td><td>Values-Based Conflict Transformation is voluntary and cannot become evidence extraction, binding judgment, title determination, or enforcement.</td></tr><tr><td>G30</td><td>SCPA execution boundary</td><td>Search, seizure, eviction, restraint, custody, force, cyber action, border action, asset freezing, and analogous execution require separate SCPA authority.</td></tr><tr><td>G31</td><td>Pilot, target, and readiness non-activation</td><td>Pilot success, certification tiers, readiness scores, 200-year projections, BAZ labels, and global targets cannot activate legal power.</td></tr><tr><td>G32</td><td>Closure and unresolved duties</td><td>Every mandate, permit, restriction, grant, mission, investigation, appointment, and delegated power ends; restoration, claims, services, compensation, correction, and protected-data duties remain without residual command.</td></tr></tbody></table> <h2>28. Compound implementation tests</h2> <table><thead><tr><th>Test</th><th>Scenario</th><th>Expected constitutional route</th></tr></thead><tbody><tr><td>T01</td><td>Satellite data shows declining soil organic matter</td><td>SOIL-05/07/08 record and interpret the evidence; SOIL-09 may alert, but no permit, payment, tax, stewardship, or title consequence follows automatically.</td></tr><tr><td>T02</td><td>Community soil sample shows microbial collapse</td><td>SOIL-05/06 protect provenance and sample sovereignty; SOIL-08 assesses causes; rights, restrictions, and emergency measures require separate routes.</td></tr><tr><td>T03</td><td>Traditional knowledge identifies a sacred soil relation</td><td>SOIL-06/14 preserve the affected nation’s authority and restricted knowledge; an outside Council cannot authenticate, publish, or convert the relation into title or zoning.</td></tr><tr><td>T04</td><td>A BAZ Council declares soil a legal person</td><td>The declaration is advisory only; SOIL-10/11 may support review and SOIL-12 links only to a competent CERGTA-13 decision.</td></tr><tr><td>T05</td><td>Soil rights overlap a farmer’s title and a tenant’s home</td><td>SOIL-04/12 preserve title, tenure, housing, services, and conflict rules; ecological recognition does not transfer land or evict occupants.</td></tr><tr><td>T06</td><td>Guardian seeks to prohibit a land use</td><td>SOIL-13 permits representation and legal standing only; any restriction requires SOIL-18/20/21 and competent authority.</td></tr><tr><td>T07</td><td>Two Indigenous nations and a landless community assert claims</td><td>SOIL-03/15 preserve all claims and applicable laws; SOIL-16 routes title and rematriation without allowing a BAZ or global council to select the claimant.</td></tr><tr><td>T08</td><td>Landowner volunteers land into a community trust</td><td>SOIL-16 routes the voluntary conversion to Hearthstone; SOIL-27 records housing, food, governance, finance, and service continuity.</td></tr><tr><td>T09</td><td>Rematriation claim is contested by occupants and workers</td><td>SOIL-15/16/44 require non-extinguishment, notice, evidence, compensation, housing, livelihood, debt, service, and appeal routes.</td></tr><tr><td>T10</td><td>Land Council adopts a Minimum Regenerative Threshold</td><td>SOIL-19 records the standard and adoption state; it does not automatically amend permits, leases, taxes, or title.</td></tr><tr><td>T11</td><td>A pesticide is proposed for phase-out</td><td>SOIL-20 requires authority, evidence, alternatives, farmer and worker transition, food effects, review, expiry, and appeal.</td></tr><tr><td>T12</td><td>Certification tier falls from Gold to Bronze</td><td>SOIL-32 corrects certification only; no permit loss, market exclusion, tenure consequence, payment clawback, or fraud finding follows automatically.</td></tr><tr><td>T13</td><td>Digital Product Passport carries a wrong Microbial Health Score</td><td>SOIL-33 propagates correction and supports interim relief; downstream authorities must reassess any separate decision.</td></tr><tr><td>T14</td><td>AUBI applicant logs microbial restoration work</td><td>SOIL-31 verifies ecological contribution and routes an independent financial decision; verification is not payment or proof of fraud.</td></tr><tr><td>T15</td><td>Wildfire causes a stewardship lease to miss targets</td><td>SOIL-28/29 identify no-fault context and support; no automatic termination, succession, or repayment occurs.</td></tr><tr><td>T16</td><td>Steward repeatedly violates a lawful plan</td><td>SOIL-29 requires notice, cure, independent verification, interim relief, appeal, succession, and remedy; any title or receivership effect routes through Hearthstone.</td></tr><tr><td>T17</td><td>Community demands veto over a proposed land sale</td><td>SOIL-25 records objection and any lawful temporary pause; a binding restriction requires exact authority, valuation, time limit, review, and remedy.</td></tr><tr><td>T18</td><td>A lawful right of first refusal is invoked</td><td>SOIL-24 governs notice, eligible holder, valuation, finance, timelines, tenants, workers, anti-circumvention, completion, and appeal.</td></tr><tr><td>T19</td><td>Land-value tax is proposed to deter speculation</td><td>SOIL-23 requires enacted authority, valuation, liable person, exemptions, housing and farm effects, hardship, revenue use, notice, and appeal.</td></tr><tr><td>T20</td><td>Community Land Trust includes housing and food production</td><td>SOIL-27 preserves tenant rights, affordability, food systems, services, governance, finance, and Hearthstone title interfaces.</td></tr><tr><td>T21</td><td>Generational stewardship lease is inherited</td><td>SOIL-26 applies the lease’s lawful succession and consent rules; a soil score cannot decide the heir or terminate occupancy.</td></tr><tr><td>T22</td><td>Soil carbon project claims credits on Indigenous land</td><td>SOIL-34/35 require affected-nation authority, benefit sharing, land and carbon-right clarification, additionality, permanence, leakage, reversal, and no double counting.</td></tr><tr><td>T23</td><td>Registry entry incorrectly identifies carbon ownership</td><td>SOIL-36 records non-constitutive status, corrects the entry, propagates correction, and preserves title and benefit claims.</td></tr><tr><td>T24</td><td>Inspector seeks entry onto a sacred site</td><td>SOIL-37 requires exact authority, affected-nation law, protected-area limits, necessity, sampling controls, notice or warrant, and remedy.</td></tr><tr><td>T25</td><td>Sensor anomaly suggests illegal dumping</td><td>SOIL-05/08 support review; SOIL-37/38 require separate authority before entry or investigation; SOIL-39 preserves alternative causes.</td></tr><tr><td>T26</td><td>Investigation finds legacy and current contamination</td><td>SOIL-39 allocates scientific confidence and alternative responsibility; adjudication independently determines liability and remedy.</td></tr><tr><td>T27</td><td>Severe contamination threatens drinking water and crops</td><td>SOIL-40 requests urgent protection while preserving water, food, housing, affected-nation, review, expiry, and compensation safeguards.</td></tr><tr><td>T28</td><td>Emergency team deploys after desertification and crop failure</td><td>SOIL-42 operates under CDEE/ECRC for civilian technical and logistical support; it cannot allocate permanent resettlement land or command coercive action.</td></tr><tr><td>T29</td><td>Emergency proposal places farms into receivership</td><td>SOIL-41 routes a separately authorized, time-limited CERGTA-43/Hearthstone process with workers, tenants, services, conflicts, review, expiry, return, and compensation.</td></tr><tr><td>T30</td><td>Microbiome Bank receives a culturally restricted sample</td><td>SOIL-06 governs access, derivative use, biosafety, benefit sharing, return or destruction; “open source” cannot override restrictions.</td></tr><tr><td>T31</td><td>Company seeks patent over a naturally occurring culture</td><td>The framework may support evidence, defensive publication, benefit-sharing, and a legal challenge, but patent invalidity requires competent law and adjudication.</td></tr><tr><td>T32</td><td>Youth delegation objects to an irreversible land plan</td><td>SOIL-18/25 require published objection, reconsideration, reasons, and review; an automatic veto exists only if lawfully enacted with scope and appeal.</td></tr><tr><td>T33</td><td>Values-Based Conflict Transformation fails</td><td>SOIL-45 records impasse without escalating automatically; mediation notes do not become evidence or binding judgment.</td></tr><tr><td>T34</td><td>Court orders remediation and compensation</td><td>SOIL-43/44 record restoration and payment duties; physical execution, seizure, eviction, or asset freezing requires SOIL-46 and SCPA.</td></tr><tr><td>T35</td><td>Pilot BAZ achieves a 10 percent soil-health improvement</td><td>SOIL-48 records the result but creates no authority to tax, restrict sales, recognize rights, expand jurisdiction, or declare the model universally valid.</td></tr><tr><td>T36</td><td>Programme closes with open contamination and tenant claims</td><td>SOIL-47 returns authority and preserves restoration, housing, claims, compensation, correction, sample, and data duties without residual command.</td></tr></tbody></table> <h2>29. Transition from v3.1</h2> <p>The following v3.1 mechanisms are retained but constitutionally reclassified:</p> <table><thead><tr><th>v3.1 mechanism</th><th>v3.2 constitutional status</th></tr></thead><tbody><tr><td>Global Soil Health Monitoring Service</td><td>knowledge and method commons under EIOI; no self-executing authority</td></tr><tr><td>Bioregional Land and Food Councils</td><td>chartered democratic bodies with separately activated and function-separated powers</td></tr><tr><td>Land Rematriation and Justice Tribunal</td><td>jurisdiction-specific independent forum; not universally created by the framework</td></tr><tr><td>Global Regenerative Agriculture Fund</td><td>separately chartered finance institution with independent eligibility, audit, and appeal</td></tr><tr><td>Open-Source Microbiome Bank</td><td>network of lawful custodians; open only where the provider chose an open licence</td></tr><tr><td>Crisis Response Mechanism</td><td>civilian Soil Emergency Assistance Missions under CDEE/ECRC</td></tr><tr><td>Global Soil Health Accord</td><td>model standard or treaty proposal; binding only after lawful adoption</td></tr><tr><td>Regenerative Agriculture Mandates</td><td>separately enacted standards, permits, restrictions, support, inspection, and remedy</td></tr><tr><td>Land Value and Anti-Speculation Tax</td><td>jurisdiction-specific tax option; no automatic Treaty trade leverage</td></tr><tr><td>Community Land Trusts and Food Commons</td><td>Hearthstone-conformant title and trust structures with housing and service safeguards</td></tr><tr><td>Soil Health Education Mandate</td><td>curriculum recommendation subject to education authority and affected-nation knowledge law</td></tr><tr><td>Planetary Health Certified labels</td><td>bounded certification; no automatic permit or market effect</td></tr><tr><td>Anti-Patent Protection for Living Cultures</td><td>legal reform and challenge pathway; no universal invalidity declaration by framework</td></tr><tr><td>Soil Carbon Rights Registry</td><td>separate methodology, benefit, issuance, retirement, and non-constitutive registry records</td></tr><tr><td>Generational Stewardship Leases</td><td>complete tenure contracts; no score-based automatic termination</td></tr><tr><td>Community Veto on Land Sales</td><td>objection, reconsideration, lawful pause, and separately enacted right-of-first-refusal or restriction</td></tr><tr><td>failing BAZ Treaty intervention</td><td>capacity support and separately authorized review; no automatic intervention</td></tr><tr><td>youth supermajority veto</td><td>model option requiring exact legal enactment, scope, review, and remedy</td></tr><tr><td>BHI, LMCI, Soil and Microbial Health thresholds</td><td>review triggers only; no automatic land, tax, permit, benefit, or enforcement effect</td></tr></tbody></table> <h2>30. Closing doctrine</h2> <blockquote><p><strong>Land is never only a commodity, but neither is it an empty surface onto which ecological institutions may write unlimited authority. It is relationship, habitat, home, livelihood, memory, law, debt, responsibility, and contested history.</strong></p></blockquote> <blockquote><p><strong>Soil v3.2 makes regeneration stronger by making every power visible: who observed, who interpreted, who consented, who owns or occupies, who planned, who taxed, who permitted, who paid, who judged, who executed, when the authority ends, and how harm is corrected.</strong></p></blockquote> <hr> <h1>Controlled cluster-adoption appendix — CEACA/0.1</h1> <p><strong>Patch version:</strong> Soil Health & Land Use Governance Framework v3.2.2<br> <strong>Substantive base:</strong> Soil Health & Land Use Governance Framework v3.2<br> <strong>Cluster release:</strong> <code>CEA-CLUSTER/0.1</code><br> <strong>Adoption specification:</strong> <code>CEACA/0.1</code><br> <strong>Authority effect of this appendix:</strong> none; it establishes compatibility, inheritance, routing, and fail-closed rules only.</p> <h2>A.1 Exact compatibility set</h2> <p>This patch participates only in the following controlled document set. A renamed body, later version, compatible-sounding policy, or partial implementation does not silently enter the release. The machine-readable cluster registry freezes the SHA-256 digest of every file.</p> <table><thead><tr><th>Instrument</th><th>Exact compatible file</th><th>Cluster role</th></tr></thead><tbody><tr><td>CERGTA/0.1</td><td><code>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</code></td><td>controlling authority interface</td></tr><tr><td>EIPHR/0.1</td><td><code>ecological-intelligence-planetary-health-role-separation-matrix-v0.1.md</code></td><td>EIOI–Planetary Health role separation</td></tr><tr><td>EIOI v2.7.1</td><td><code>ecological-intelligence-observation-interpretation-layer-v2.7.1.md</code></td><td>ecological observation, provenance, methods, uncertainty, interpretation, and advisory alerts</td></tr><tr><td>PHG v0.9.1</td><td><code>planetary-health-governance-framework-v0.9.1.md</code></td><td>independent synthesis, participatory audit, cross-domain coherence, and strategic recommendation</td></tr><tr><td>HEARTHSTONE v2.0.1</td><td><code>hearthstone-protocol-v2.0.1.md</code></td><td>voluntary conversion, claims support, title and tenure interfaces, trusts, rematriation, stewardship, and transition</td></tr><tr><td>WATER v5.2.2</td><td><code>water-sanitation-governance-framework-v5.2.2.md</code></td><td>watershed democracy, universal WASH, allocation, utilities, tariffs, guardianship interfaces, and emergency WASH</td></tr><tr><td>BIODIVERSITY v1.1.1</td><td><code>biodiversity-implementation-framework-v1.1.1.md</code></td><td>Indigenous-led stewardship support, restoration programmes, rights-review support, biodiversity finance interfaces, and accountability</td></tr><tr><td>OCEANS v2.3.1</td><td><code>oceans-marine-governance-framework-v2.3.1.md</code></td><td>marine stewardship, quotas and licensing interfaces, port-state measures, crew protection, precaution, and marine emergencies</td></tr><tr><td>SOIL v3.2.2</td><td><code>soil-health-land-use-governance-framework-v3.2.2.md</code></td><td>living-soil protection, regenerative land-use programmes, microbial commons, tenure interfaces, certification, and remediation</td></tr><tr><td>MOS v2.8.2</td><td><code>moral-operating-system-v2.8.2.md</code></td><td>advisory ethical deliberation, rights imagination, plural translation, and structural self-correction</td></tr></tbody></table> <h2>A.2 Controlling rules</h2> <ol><li><code>CERGTA/0.1</code> controls the separation of observation, interpretation, rights review, legal recognition, guardianship, affected Indigenous-nation authority, sacred and biocultural designation, claims, title, tenure, stewardship, allocation, permitting, inspection, urgent protection, restrictions, finance, adjudication, restoration, and closure.</li> <li><code>EIPHR/0.1</code> controls the division among EIOI, the Planetary Health Synthesis Office, and the Planetary Health Council. EIOI supplies evidence; PHSO compiles modular synthesis; PHC interprets and recommends. None may create a downstream legal or financial consequence.</li> <li>MOS is advisory only. Its Dynamic Rights Spectrum, philosophical language, developmental translations, structural-failure hypotheses, and guardianship metaphors never create legal status, classify persons, determine credibility, establish Indigenous consent, or activate consequential action.</li> <li>Hearthstone controls the cluster interface for claims, competing claims, title, tenure, trust constitution, voluntary conversion, rematriation, compensation, debt, tenants, workers, registry correction, receivership, succession, and dissolution. Sectoral ecological frameworks may provide evidence or programme support but cannot decide those questions by implication.</li> <li>Water, Biodiversity, Oceans, and Soil retain only the powers separately constituted in applicable law and recorded through the relevant CERGTA route. Framework membership, a council vote, a dashboard value, a target, a pilot, a future date, or a coalition size does not activate authority.</li> <li>Emergency identity and coordination use CDEE and ECRC. Ecological urgency does not create emergency command, and an emergency declaration does not create ecological title, guardianship, permanent restrictions, receivership, or enforcement authority.</li> <li>Search, seizure, restraint, custody, force, cyber action, border action, intelligence use, asset freezing, or analogous coercive execution requires separate SCPA authority. A commons or ecological claim may justify review; it does not authorize a raid.</li> <li>The specific affected Indigenous nation or nations determine their representatives, applicable law, territorial and relational authority, consent process, internal plurality, protected knowledge, and whether to participate. Global or framework-created Indigenous bodies may support or audit but cannot consent or waive rights for another people.</li> <li>Essential minimums for water, sanitation, health, disability support, food, shelter, rescue, crew welfare, and ecological survival remain protected from commercial, tariff, certification, funding, listing, or transition leverage.</li> <li>Every handoff uses the canonical CERGTA states. Receipt, technical ingestion, silence, consultation, or partial use is not acceptance and never creates authority.</li> <li>Every consequential route keeps its own legal basis, decision-maker, affected persons, evidence, access controls, clock, expiry, challenge, correction, remedy, termination, and data-disposition record.</li> <li>Unknown, missing, stale, or incompatible versions fail closed for consequential action. Non-coercive care, emergency life-safety support, accessibility, explanation, and correction should continue wherever lawful and safe.</li></ol> <h2>A.3 Record inheritance and packaging</h2> <p>A local record may implement, extend, split, contain, import, or mark a CERGTA record not applicable. It may not erase the canonical identity, merge distinct powers, weaken an affected-person safeguard, or use a compound package to supply a missing legal basis.</p> <p>The forty-field CERGTA header, access classification, handoff state, independent clocks, correction propagation, remedy, termination, authority return, and data disposition are inherited wherever the substantive base creates or transports a consequential record. Advisory and observation-only records must state their prohibited inferences.</p> <h2>A.4 Registry and compatibility failure</h2> <p>The file <code>commons-ecological-authority-cluster-conformance-registry-v0.1.json</code> is the machine-readable release registry. It is evidence of the exact release set, not an authority record. A hash mismatch, missing component, unsupported local extension, or unresolved version conflict changes the compatibility state to <code>failed_closed</code>.</p> <p>A compatibility failure blocks new consequential cross-framework handoffs. It does not by itself terminate independently valid local law, erase existing rights, interrupt essential services, or authorize emergency or coercive action.</p> <h2>A.5 Closure</h2> <p>A cluster transaction closes only after all accepted handoffs, powers, services, persons, property, guardianship duties, claims, title or tenure effects, financial actions, emergency dependencies, coercive dependencies, corrections, remedies, clocks, credentials, records, and residual risks are resolved or assigned to a named lawful custodian without preserving expired power.</p> <h2>A.6 Editorial patch note — v3.2.1 → v3.2.2</h2> <p>This patch is <strong>editorial only</strong>. No doctrine, power, boundary, record, gate, or test was added, removed, or weakened. The substantive base remains v3.1 as audited, and all forty-eight SOIL records retain their identity, title, and purpose.</p> <p>Changes:</p> <ol><li><strong>§25 record catalogue.</strong> Forty-eight headed subsections became a single table. The sentence <code>This record creates no authority beyond the exact constituting instrument named in its inherited CERGTA header</code> appeared verbatim forty-eight times; it is now stated once as a minimum rule governing every record in the table. Record IDs, titles, and purpose text are unchanged.</li> <li><strong>§26 crosswalk.</strong> The conformance-note column was generated from each record’s own title for forty-five of fifty-four rows, carrying no information beyond the mapping already shown. The default is now stated once above the table, and the nine rows that carried a substantive boundary are preserved verbatim in §26.1.</li> <li><strong>§1 source freeze.</strong> Clarified as a provenance record rather than an operative dependency set, resolving an ambiguity against Appendix A.1. The v3.1 pin now uses the canonical filename instead of a local download-artifact name (<code>v3.1_2.md</code>); the digest is unchanged and remains valid, as content hashes are name-independent.</li> <li><strong>A.1 compatibility set.</strong> Updated to reflect the editorial patches to Water, Soil, and MOS.</li></ol> <p>Downstream switching cost, disclosed rather than absorbed silently: any cluster document whose A.1 table names <code>water-sanitation-governance-framework-v5.2.1.md</code>, <code>soil-health-land-use-governance-framework-v3.2.1.md</code>, or <code>moral-operating-system-v2.8.1.md</code> must update those three lines and the registry JSON, or its compatibility state is <code>failed_closed</code> under A.4. Because the change is editorial, the correct response is to update the pin, not to treat the mismatch as a substantive conflict.</p>',1);function c(e){var t=r();o(362),n(e,t)}export{c as default};
